  function labelForDirection(v){const names=[['L','R'],['P','A'],['I','S']];let axis=0;if(Math.abs(v[1])>Math.abs(v[axis]))axis=1;if(Math.abs(v[2])>Math.abs(v[axis]))axis=2;return v[axis]>=0?names[axis][1]:names[axis][0];}
