  function updateTargetPulsePosition(ctx){const node=ctx&&ctx.root&&ctx.root.querySelector('[data-imaging-3d-target-pulse]'),marker=ctx&&ctx.state&&ctx.state.extremumMarker;if(!node)return false;if(!marker||!ctx.renderer){node.hidden=true;node.classList.remove('isPulsing');return false;}if(typeof ctx.renderer.projectWorldToCanvas!=='function')throw new Error('3-D target projection requires the mounted mesh renderer projection authority.');const projected=ctx.renderer.projectWorldToCanvas(marker.worldMm);if(!projected||!projected.visible){node.hidden=true;node.classList.remove('isPulsing');return false;}node.hidden=false;node.style.left=`${projected.x}px`;node.style.top=`${projected.y}px`;return true;}
