    if(field==='surfaceDepth'){if(phase!=='commit')return;a.surfaceDepthMm=clamp(finite(value,0),0,a.maxSurfaceDepthMm);ctx.notify(state,'3d_surface_depth');if(ctx.remount)ctx.remount();return;}
